import PDFDocument from "pdfkit";

// Every report - department or crop, any period - is laid out the same way:
//
//   Keiyian Farmers Cooperative Society Ltd
//   Nuru ya Jamii
//   Sales report - November 2026
//   Generated by <name> on 08 Nov 2026, 21:24 EAT
//
// then a Summary table, one ruled table per section, the sign-off lines and,
// on every page, "This is a system generated report." with the time.
//
// A report: { heading, summary: [{ label, value, type? }], sections: [{ title, columns, rows, totals?, totalLabel? }] }

export const ORGANISATION = "Keiyian Farmers Cooperative Society Ltd";
export const MOTTO = "Nuru ya Jamii";
export const SIGN_OFF = ["Prepared by", "Checked by", "Confirmed by"];
export const SYSTEM_NOTE = "This is a system generated report.";

const SHORT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const NUMERIC = ["money", "number", "percent"];

const money = (value) => Number(value || 0).toLocaleString("en-KE", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const number = (value) => (value === "" || value == null ? "" : Number(value).toLocaleString("en-KE", { maximumFractionDigits: 2 }));
const percent = (value) => (value === "" || value == null ? "" : `${number(value)}%`);
/** "02 May 2024" */
const dateText = (value) => {
  if (!value) return "";
  const d = new Date(value);
  return `${String(d.getUTCDate()).padStart(2, "0")} ${SHORT[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
};
const isoText = (value) => (value ? new Date(value).toISOString().slice(0, 10) : "");

/** "08 Nov 2026, 21:24 EAT" - the cooperative works in Nairobi time. */
export const generatedStamp = (date = new Date()) =>
  `${date.toLocaleString("en-GB", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", hour12: false, timeZone: "Africa/Nairobi" })} EAT`;

export const formatCell = (value, type) => {
  if (type === "percent") return percent(value);
  if (type === "money") return value === "" || value == null ? "" : money(value);
  if (type === "number") return number(value);
  if (type === "date" || value instanceof Date) return dateText(value);
  return value == null ? "" : String(value);
};

/** A summary figure as it reads in the Summary table. */
export const summaryText = (item) => {
  if (item.type === "money") return `KES ${money(item.value)}`;
  if (item.type === "percent") return percent(item.value);
  if (item.type === "text") return String(item.value ?? "");
  return number(item.value);
};

/** The report's key figures as a two-column table. */
export const summarySection = (report) => ({
  title: "Summary",
  columns: [{ key: "item", label: "Item" }, { key: "value", label: "Value", align: "right" }],
  rows: report.summary.map((item) => ({ item: item.label, value: summaryText(item) })),
  width: 0.5,
});

const options = (meta) => ({
  organisation: meta.organisation || ORGANISATION,
  motto: meta.motto ?? MOTTO,
  generatedBy: meta.generatedBy || "the system",
  generated: generatedStamp(meta.generatedAt ? new Date(meta.generatedAt) : new Date()),
  emptyText: meta.emptyText || "No records for this period.",
  signatures: meta.signatures || SIGN_OFF,
});

// ---------------------------------------------------------------------
// CSV (opens in Excel): each report's header, Summary, then its tables.
// ---------------------------------------------------------------------
const csvCell = (value) => {
  const text = value == null ? "" : String(value);
  return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
};
const csvRaw = (value, type) => {
  if (value instanceof Date || type === "date") return isoText(value);
  if (NUMERIC.includes(type)) return value === "" || value == null ? "" : Number(value);
  return value;
};

export const toCsv = (reports, meta) => {
  const { organisation, motto, generatedBy, generated } = options(meta);
  const lines = [];
  const row = (cells) => lines.push(cells.map(csvCell).join(","));
  reports.forEach((report, index) => {
    if (index > 0) lines.push("", "");
    row([organisation]);
    if (motto) row([motto]);
    row([report.heading]);
    row([`Generated by ${generatedBy} on ${generated}`]);
    lines.push("");
    row(["Summary"]);
    row(["Item", "Value"]);
    for (const item of report.summary) row([item.label, item.type === "text" ? item.value : csvRaw(item.value, item.type || "number")]);
    for (const section of report.sections) {
      lines.push("");
      row([section.title]);
      row(section.columns.map((c) => c.label));
      if (!section.rows.length) row(["No records"]);
      for (const data of section.rows) row(section.columns.map((c) => csvRaw(data[c.key], c.type)));
      if (section.totals) row(section.columns.map((c, i) => (i === 0 ? section.totalLabel || "Total" : section.totals[c.key] ?? "")));
    }
  });
  lines.push("");
  row([SYSTEM_NOTE]);
  row(["Generated", generated, "by", generatedBy]);
  return `﻿${lines.join("\r\n")}\r\n`;
};

// ---------------------------------------------------------------------
// PDF: A4 landscape. Centred header, then ruled tables (rows and columns).
// ---------------------------------------------------------------------
const GREEN = "#40532a";
const INK = "#19271f";
const MUTED = "#5e6b5e";
const RED = "#9f1239";
const GRID = "#b7c4b2";
const HEAD_FILL = "#e6ede2";
const TOTAL_FILL = "#f1f5ef";

const looksNegative = (text) => /^(KES )?-\d/.test(text);

export const toPdf = (reports, meta) => new Promise((resolve, reject) => {
  const { organisation, motto, generatedBy, generated, emptyText, signatures } = options(meta);
  const doc = new PDFDocument({
    size: "A4",
    layout: "landscape",
    margin: 36,
    bufferPages: true,
    info: { Title: reports.map((r) => r.heading).join("; ") || "Report", Author: organisation },
  });
  const chunks = [];
  doc.on("data", (chunk) => chunks.push(chunk));
  doc.on("end", () => resolve(Buffer.concat(chunks)));
  doc.on("error", reject);

  const left = doc.page.margins.left;
  const width = doc.page.width - doc.page.margins.left - doc.page.margins.right;
  const bottom = () => doc.page.height - doc.page.margins.bottom - 20;
  const ensure = (height) => {
    if (doc.y + height > bottom()) doc.addPage();
  };

  const header = (report) => {
    doc.fillColor(GREEN).font("Helvetica-Bold").fontSize(15).text(organisation, left, doc.page.margins.top, { width, align: "center" });
    if (motto) doc.fillColor(MUTED).font("Helvetica-Oblique").fontSize(9.5).text(motto, { width, align: "center" });
    doc.moveDown(0.4);
    doc.fillColor(INK).font("Helvetica-Bold").fontSize(12.5).text(report.heading, { width, align: "center" });
    doc.fillColor(MUTED).font("Helvetica").fontSize(9).text(`Generated by ${generatedBy} on ${generated}`, { width, align: "center" });
    const y = doc.y + 6;
    doc.moveTo(left, y).lineTo(left + width, y).strokeColor(GREEN).lineWidth(1.5).stroke();
    doc.x = left;
    doc.y = y + 12;
  };

  const table = (section) => {
    const tableWidth = section.width ? width * section.width : width;
    const columns = section.columns;
    const right = (c) => c.align === "right" || NUMERIC.includes(c.type);
    // Text columns get twice the width of number columns unless told otherwise.
    const weights = columns.map((c) => c.weight ?? (right(c) ? 1 : 2));
    const unit = tableWidth / weights.reduce((a, b) => a + b, 0);
    const widths = weights.map((w) => w * unit);
    const headerCells = columns.map((c) => c.label);

    ensure(56);
    doc.x = left;
    doc.fillColor(GREEN).font("Helvetica-Bold").fontSize(10.5).text(section.title, left);
    doc.moveDown(0.25);

    const drawRow = (cells, { bold = false, fill, isHeader = false } = {}) => {
      const font = bold ? "Helvetica-Bold" : "Helvetica";
      doc.font(font).fontSize(8.5);
      const height = Math.max(...cells.map((cell, i) => doc.heightOfString(cell || " ", { width: widths[i] - 8 })), 10) + 7;
      if (doc.y + height > bottom()) {
        doc.addPage();
        // Repeat the column headings at the top of the new page.
        if (!isHeader) drawRow(headerCells, { bold: true, fill: HEAD_FILL, isHeader: true });
      }
      const y = doc.y;
      if (fill) doc.rect(left, y, tableWidth, height).fill(fill);
      let x = left;
      cells.forEach((cell, i) => {
        const text = cell ?? "";
        doc.fillColor(!isHeader && right(columns[i]) && looksNegative(text) ? RED : INK).font(font).fontSize(8.5)
          .text(text, x + 4, y + 3.5, { width: widths[i] - 8, align: right(columns[i]) ? "right" : "left" });
        x += widths[i];
      });
      // Grid: the row's outline and the lines between its cells.
      doc.lineWidth(0.5).strokeColor(GRID).rect(left, y, tableWidth, height).stroke();
      let lineX = left;
      for (let i = 0; i < widths.length - 1; i += 1) {
        lineX += widths[i];
        doc.moveTo(lineX, y).lineTo(lineX, y + height).stroke();
      }
      doc.y = y + height;
    };

    drawRow(headerCells, { bold: true, fill: HEAD_FILL, isHeader: true });
    if (!section.rows.length) {
      const y = doc.y;
      doc.fillColor(MUTED).font("Helvetica-Oblique").fontSize(8.5).text(emptyText, left + 4, y + 3.5, { width: tableWidth - 8 });
      doc.lineWidth(0.5).strokeColor(GRID).rect(left, y, tableWidth, 17).stroke();
      doc.y = y + 17;
    }
    for (const data of section.rows) drawRow(columns.map((c) => formatCell(data[c.key], c.type)));
    if (section.totals) {
      drawRow(columns.map((c, i) => (i === 0 ? section.totalLabel || "Total" : section.totals[c.key] == null ? "" : formatCell(section.totals[c.key], c.type))), { bold: true, fill: TOTAL_FILL });
    }
    doc.x = left;
    doc.moveDown(1);
  };

  const signOff = () => {
    ensure(24 + signatures.length * 24);
    doc.moveDown(1);
    for (const role of signatures) {
      doc.fillColor(INK).font("Helvetica").fontSize(9)
        .text(`${role}: ______________________________      Signature: ____________________      Date: ______________`, left);
      doc.moveDown(1.2);
    }
  };

  // Each report starts on its own page and is signed off on its own.
  reports.forEach((report, index) => {
    if (index > 0) doc.addPage();
    header(report);
    table(summarySection(report));
    report.sections.forEach(table);
    signOff();
  });

  // Footer on every page: the system note with when it was generated, and
  // the page number. It sits in the bottom margin; lift the margin while
  // writing so the text does not spill onto a new, blank page.
  const range = doc.bufferedPageRange();
  for (let i = range.start; i < range.start + range.count; i += 1) {
    doc.switchToPage(i);
    const margin = doc.page.margins.bottom;
    doc.page.margins.bottom = 0;
    const y = doc.page.height - margin + 8;
    doc.moveTo(left, y - 5).lineTo(left + width, y - 5).strokeColor(GRID).lineWidth(0.5).stroke();
    doc.fillColor(MUTED).font("Helvetica-Oblique").fontSize(7.5).text(`${SYSTEM_NOTE} Generated ${generated}.`, left, y, { width: width - 80, lineBreak: false });
    doc.font("Helvetica").text(`Page ${i + 1} of ${range.count}`, left, y, { width, align: "right", lineBreak: false });
    doc.page.margins.bottom = margin;
  }
  doc.end();
});
